// Stage 1 · Normalize: every lane already parsed its own rows; make them one shape.
const clean = (s) => String(s || '').trim();
return $input.all().map(({ json }) => ({ json: {
  company: clean(json.company || json.target || json.name),
  website: clean(json.website).toLowerCase().replace(/^https?:\/\/(www\.)?/, '').replace(/\/.*$/, ''),
  sector: clean(json.sector || json.description),
  release_url: clean(json.release_url || json.url),
  source_lane: clean(json.source_lane || 'unknown'),
  known_websites: json.known_websites || [],
} }));

// Stage 2 · Dedupe + scope, before any paid step.
// Duplicates: same website already on file, or twice in this batch. Scope: keyword check on the sector text.
const IN_SCOPE = /software|saas|data|cloud|platform|analytics|cyber|it services/i;
const seen = new Set();
return $input.all().map(({ json }) => {
  const known = new Set((json.known_websites || []).map((w) => String(w).toLowerCase()));
  let skip = '';
  if (!json.company) skip = 'no company name';
  else if (json.website && (known.has(json.website) || seen.has(json.website))) skip = 'duplicate';
  else if (json.sector && !IN_SCOPE.test(json.sector)) skip = 'out of scope';
  if (json.website) seen.add(json.website);
  return { json: { ...json, keep: !skip, skip_reason: skip } };
});

// Every row leaves a log line, including the ones that exit early.
return $input.all().map(({ json }) => ({ json: {
  logged_at: new Date().toISOString(),
  lane: json.source_lane,
  company: json.company,
  outcome: 'skipped',
  reason: json.skip_reason,
} }));
